CustomCss:
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;letter-spacing:.1px}
h1,h2,h3,.nlbl{font-family:ui-serif,Georgia,'Iowan Old Style','Times New Roman',serif;font-weight:600;letter-spacing:.2px}
h1,h2{color:var(--t)}
h2{padding-bottom:10px;border-bottom:1px solid var(--b);margin-bottom:16px}
.nav,.form,.sc,table,.field{border-radius:10px}
.nav{background:var(--s)}
.ni{border-radius:8px;transition:background .15s ease,color .15s ease,transform .12s ease}
.ni:hover{transform:translateX(2px)}
.ni.active{background:var(--hover);color:var(--a);font-weight:600}
.ni.active svg{color:var(--a)}
.form,.sc{border:1px solid var(--b);box-shadow:0 1px 2px rgba(31,30,27,.03);transition:border-color .15s ease,box-shadow .15s ease}
.form:hover,.sc:hover{border-color:var(--a);box-shadow:0 2px 10px rgba(204,120,92,.08)}
.pnl.active{animation:antIn .28s ease}
@keyframes antIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
button.bp,button.bd,button.bw,button.bsm{border-radius:8px;font-weight:600;letter-spacing:.2px;transition:transform .1s ease,box-shadow .12s ease,opacity .12s ease}
button.bp:hover,button.bd:hover,button.bw:hover,button.bsm:hover{transform:translateY(-1px)}
button.bp{background:var(--a);box-shadow:0 1px 3px rgba(204,120,92,.35)}
button.bp:hover{box-shadow:0 3px 10px rgba(204,120,92,.4)}
input,select,textarea{border-radius:7px}
input:focus,select:focus,textarea:focus{border-color:var(--a);box-shadow:0 0 0 3px rgba(204,120,92,.18)}
table{border:1px solid var(--b);overflow:hidden}
th{background:var(--s);font-weight:600}
td,th{border-bottom:1px solid var(--b)}
.sc .v{color:var(--a);font-family:ui-serif,Georgia,serif}
.theme-toggle,.theme-sel{border-radius:8px}
.msg.ok{border-left:3px solid var(--g)}
.msg.err{border-left:3px solid var(--r)}
